-- ==============================================================================
-- Migration V13: Bổ sung giảng viên đầy đủ cho tất cả các khoa (Mỗi khoa từ 12-37 GV)
-- ==============================================================================

BEGIN;

-- 1. Insert Users for 164 new teachers (teacher56 -> teacher219)

-- 2. Assign ROLE_TEACHER (role_id = 2)

-- 3. Insert into teachers table

-- 4. Assign new teachers to courses of their respective departments in course_teachers
SELECT c.id, t.id
FROM teachers t
JOIN courses c ON c.department_id = t.department_id
WHERE t.id >= 56
ON CONFLICT (course_id, teacher_id) DO NOTHING;

-- 5. Reassign or balance class_sections for depts 12, 13, 14, 15 to actual teachers of those depts
UPDATE class_sections cs
SET teacher_id = sub.new_teacher_id
FROM (
    SELECT cs2.id as class_section_id,
           (SELECT t.id FROM teachers t WHERE t.department_id = c.department_id ORDER BY (cs2.id * 17 + t.id) % 13 LIMIT 1) as new_teacher_id
    FROM class_sections cs2
    JOIN courses c ON cs2.course_id = c.id
    WHERE c.department_id IN (12, 13, 14, 15)
) sub
WHERE cs.id = sub.class_section_id AND sub.new_teacher_id IS NOT NULL;

COMMIT;
